) AS (
  VALUES 
    (144::BIGINT, 'La profe es muy seria, será mejor que preste atención y no pregunte, por que se enoja. Las instrucciones que deja son claras y si sigue todo al pie pasa fácil.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2026-08-06T00:00:00+00:00'::TIMESTAMPTZ, 'd6211f0de5c6d0ced69d10026e4bcd5ae36c93249de59444e7d2bdab1f000c32'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'Demasiado carga, muy facil de pasar con ella. Aparte, si soy aplicado es más relajada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2026-07-19T00:00:00+00:00'::TIMESTAMPTZ, '736edbd511450a4ede45f985f4c0eef5922e52eba56eb37efed5f0bc901e511f'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'Buena profe, tiene una personalidad recia y enfocada que la hace súper organizada y profesional pero a algunas personas esto les podría molestar. A mí me gustó su curso, muy organizado y conciso y bastante fácil además de que fue virtual, recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'La participación importa']::TEXT[], '2026-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'ecd76e0ebd5e5f50c679f6d0c1e381789b65ca617b1dbfd04ac62e06f07c3f96'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'Es buena, lleve con ella virtual. Muy ordenada con las consignas. Aveces agarra a estudiantes como asistentes. Califica duro, un poco necia, puede llegar a ser un poco intimidante pero es buena persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2026-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'ec4de42e2b1f692a974f717cc330f0d05240ce49a20022b98868ed884110958d'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'Es muy buena profe y ayuda demasiado, espera de los estudiantes que se comporten como adultos y realmente muestren interés en el aprendizaje, algo básico, ayuda en todo lo que uno ocupe, el tiempo que uno ocupe, es super divertida y buena gente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2026-04-04T00:00:00+00:00'::TIMESTAMPTZ, '1c6f25431f66449677c9e004bfb939aa1b5931d88b2b4e6aa3cf665877f3a9d8'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'Al inicio puede parecer un poco intimidante sin embargo, en el transcurso de las clases vas agarrando confianza qué ella misma te demuestra y siempre tiene una buena intención de hacerte entender todas sus instrucciones las cuales son muy claras y es una maravilla de persona y profesional.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Brinda apoyo']::TEXT[], '2026-02-20T00:00:00+00:00'::TIMESTAMPTZ, '0fd39da0318463bbb5ba919d86cca8e7b751a18f9a58bb03eedf5e6aeb74d0c6'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'La profe es super linda persona, se convierte como en una amiga, es muy ordenada y clara en las instrucciones, si es medio estricta pero si usted hace las cosas al pie de la letra se pasa fácil con un 100, califica justo y se aprende bastante, la recomiendo totalmente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2025-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'a21898011150e93c7b56f32e74f828481ef3ab872064ee1b66c6e9749bad85f2'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'A pesar de que en clases aparenta ser estricta es muy amable y califica bien, si no tiene ansiedad social se puede ofrecer como voluntario para que le haga las correcciones de los trabajos frente a todos antes de entregarlos y asegurar un 100 en los mismos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-08-11T00:00:00+00:00'::TIMESTAMPTZ, '812bc15faaeca3bc675dd1b4ecae482357ab9ae36c43d3dcc180e976e2d92ba8'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'me parece una increible profesora, me agrada su método de estudio y su claridad. Siempre conservar el respeto en su clase y todo fluira.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2025-06-18T00:00:00+00:00'::TIMESTAMPTZ, '608f1a1704890ac0548133516a2dd0362995a2753082a85e7c909c3880b973ce'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'La profe al inicio asusta, pero a como van pasando las clases se hace muy amiga de uno, ella es muy organizada por lo que se debe llevar los trabajos bien, las clases son largas porque explica muy bien y siempre explica bastante. Es una profe que recomiendo si en verdad quieren aprender...'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2025-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'cf823f7f10c517fffa0c18eafd53435b05b76f22a70a0ac56bf2fd472458fdd3'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'Aunque la proe de primera entrada da un poco de miedo, realmente es super buena nota. Es muy clara con las instrucciones, y aunque intimida un poco, realmente califica bonito y el curso se pasa haciendo los trabajos facil. Solo no se duerman en clase por que no le gusta para nada. Es muy buena profe'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-02T00:00:00+00:00'::TIMESTAMPTZ, '4db1cc10ebd3691b1e2ebe660928e79527d457a501db9818aa25fd8e4989af69'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'Las clases son largas, habla mucho y suele ser tedioso pero es una buena profe'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-05-31T00:00:00+00:00'::TIMESTAMPTZ, '05732822c9a253e4aefa212eb589ef1b2aaf7e8a978d08bff1a909f8ae115d0d'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'Excelente profe, hay que prestar bastante atención a las indicaciones que realizar, muy ordenada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2025-01-29T00:00:00+00:00'::TIMESTAMPTZ, '1a0ce19c090cec144dfa2aff9aa82d101ecc982e071ce92a78d1bb33d4854a2a'::TEXT, ARRAY[600]::BIGINT[]),
    (144::BIGINT, 'Una profe muy buena, puede que la clase llegue a ser tediosa, pero deja la materia muy clara. Los trabajos que deja son sencillos y las instrucciones también son claras.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2024-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'cc5600376fdba730a1f9ff11aecaf450c6c895c7f857d0893fe91ae44d99907b'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'bffb319d5bbd5fc7cbf09177872baed9b21b5f2807c9a68db9190922e06eb7f8'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-05-16T00:00:00+00:00'::TIMESTAMPTZ, '38d807e23c434f2a68abbb514eaa6b2636b4dd951c424ef3282c9e3db2d9a039'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'Excelente profesora, trabaja de forma ordenada y todo al dia, es muy clara en lo que pide. Pocos trabajos (2 tareas, 2 trabajos largos dividos en avances). Se interesa de que a final de clase todo este claro. Eso si, no puede faltar a clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2022-06-04T00:00:00+00:00'::TIMESTAMPTZ, '8dbcb0d94f50d0262a5fb753f73009cd2bc165fac1bd4969bfae226dc8a24cfe'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'La profe Larissa es una excelente opción. Eso sí, sea claro con lo que ella pide y vaya a clases, ya que si no lo puede sacar del curso, cosa que hizo con una compañera este semestre. Los trabajos son extensos pero es lo normal del curso.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2021-07-24T00:00:00+00:00'::TIMESTAMPTZ, 'f22cd059f5a9326525f7786c055eba86844961861dfdcab771cebc4c02f3768f'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'Demasiado buena, deja muy pocos trabajos y súper sencillos. El más "complicado" sería el ensayo, que igualmente no es difícil, y además da mucho tiempo para realizarlo.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'b99a75d66668093cd8cc9ac0af662e6691030b5f473e628b9a6e4511d368eb23'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'Estricta, pero si haces todo al pie de la letra, te va bien, vas a aprender de verdad y debes esforzarte.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2021-07-04T00:00:00+00:00'::TIMESTAMPTZ, '1257b3276d1cb8f27922f2e9e2887a9b9de32276062ebc793a0c232114a3ce4d'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'Es muy buena profesora. Da la sensación de que es repugnante, pero si pones atención no será así. Deja relativamente pocos trabajos, pero si conllevan tiempo y dedicación, eso si quieres hacer un buen trabajo. Sabe bastante y es un tanto amable. Es estricta, pero si llevaría otro curso con ella'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'a29792b90e6dce202b2cd919668bd770440fbf75a6a342a91ce5c15cb8065dfc'::TEXT, ARRAY[554]::BIGINT[]),
    (144::BIGINT, 'Muy estrict, pero excelente profesora, no duden en matricular con ella, explica super bien y le pone mucho al a lo que hace. Lo llevé en modalidad virtual'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-24T00:00:00+00:00'::TIMESTAMPTZ, '162e64410ff1d90327d5ef9b0b00f66e29bf3af61dbdd248801d8487108924eb'::TEXT, ARRAY[600]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
